/// <summary>
/// A handheld's check-in - see HSMobileOpsSkuPageService::heartbeat: it is on, and what waits in
/// its posting queue (OldestQueuedSeconds: how long the oldest has waited).
/// </summary>
[DataContractAttribute]
class HSMobileOpsDeviceHeartbeat
{
    str dataAreaId;
    str deviceId;
    str warehouse;
    int queuePending;
    int queueFailed;
    int oldestQueuedSeconds;
    str appVersion;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('Warehouse')]
public str parmWarehouse(str _value = warehouse)
{
    warehouse = _value;
    return warehouse;
}

[DataMemberAttribute('QueuePending')]
public int parmQueuePending(int _value = queuePending)
{
    queuePending = _value;
    return queuePending;
}

[DataMemberAttribute('QueueFailed')]
public int parmQueueFailed(int _value = queueFailed)
{
    queueFailed = _value;
    return queueFailed;
}

[DataMemberAttribute('OldestQueuedSeconds')]
public int parmOldestQueuedSeconds(int _value = oldestQueuedSeconds)
{
    oldestQueuedSeconds = _value;
    return oldestQueuedSeconds;
}

[DataMemberAttribute('AppVersion')]
public str parmAppVersion(str _value = appVersion)
{
    appVersion = _value;
    return appVersion;
}
